@Tags(['golden'])
library;

// T-209: Insights v2 Overview goldens, ar + en, light + dark, plus the
// hidden-amounts and the scrub states. PNGs are generated by the CI
// `app-regen` workflow (commit message tag), not committed from here.

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/core/l10n/date_format.dart';
import 'package:zaghlol/features/insights/presentation/v2/insights_v2_screen.dart';

import '../../../../support/hide_amounts_support.dart';
import 'v2_test_support.dart';

Future<void> _pump(
  WidgetTester tester, {
  required Locale locale,
  required bool dark,
  bool hidden = false,
}) async {
  await initDateFormatting();
  await tester.binding.setSurfaceSize(const Size(390, 2100));
  addTearDown(() => tester.binding.setSurfaceSize(null));
  await tester.pumpWidget(
    harness(
      const RepaintBoundary(
        key: ValueKey('golden-root'),
        child: ChartsV2Screen(),
      ),
      locale: locale,
      dark: dark,
      hideAmounts: hidden ? HideAmountsHarness(hidden: true) : null,
      overrides: v2Overrides(),
    ),
  );
  await tester.pumpAndSettle();
}

void main() {
  for (final locale in const [Locale('ar', 'EG'), Locale('en')]) {
    for (final dark in [false, true]) {
      final name = '${locale.languageCode}_${dark ? 'dark' : 'light'}';
      testWidgets('insights v2 overview golden $name', (tester) async {
        await _pump(tester, locale: locale, dark: dark);
        await expectLater(
          find.byKey(const ValueKey('golden-root')),
          matchesGoldenFile(
            '../../../../goldens/insights_v2_overview_$name.png',
          ),
        );
      });
    }
    final name = '${locale.languageCode}_light';
    testWidgets('insights v2 overview hidden golden $name', (tester) async {
      await _pump(tester, locale: locale, dark: false, hidden: true);
      await expectLater(
        find.byKey(const ValueKey('golden-root')),
        matchesGoldenFile(
          '../../../../goldens/insights_v2_overview_hidden_$name.png',
        ),
      );
    });
    testWidgets('insights v2 overview scrub golden $name', (tester) async {
      await _pump(tester, locale: locale, dark: false);
      final chart = find.byKey(const Key('pace-chart'));
      final topLeft = tester.getTopLeft(chart);
      final w = tester.getSize(chart).width;
      final h = tester.getSize(chart).height;
      final rtl = locale.languageCode == 'ar';
      final f = 13 / 30;
      final dx = rtl ? (w - 8) - f * (w - 60) : 8 + f * (w - 60);
      final g = await tester.startGesture(topLeft + Offset(w / 2, h / 2));
      await g.moveBy(const Offset(30, 0));
      await tester.pump();
      await g.moveTo(topLeft + Offset(dx, h / 2));
      await tester.pump();
      await expectLater(
        find.byKey(const ValueKey('golden-root')),
        matchesGoldenFile('../../../../goldens/insights_v2_scrub_$name.png'),
      );
      await g.up();
    });
  }
}
